import { createHash } from "node:crypto";
import { mkdir, readFile, readdir, stat, writeFile } from "node:fs/promises";
import { extname, join, relative } from "node:path";

const projectRoot = new URL("..", import.meta.url).pathname.replace(/^\//, "");
const sourceRoot = join(projectRoot, "src", "agent", "skills", "minimax-h3");
const outputPath = join(projectRoot, "src", "agent", "generated", "h3Skills.ts");
const textExtensions = new Set([".md", ".txt", ".yaml", ".yml", ".json", ".toml", ".xml", ".csv"]);

function toPosixPath(value) {
  return value.replaceAll("\\", "/");
}

function mimeTypeFor(filePath) {
  const extension = extname(filePath).toLowerCase();
  return {
    ".md": "text/markdown",
    ".txt": "text/plain",
    ".yaml": "text/yaml",
    ".yml": "text/yaml",
    ".json": "application/json",
    ".toml": "application/toml",
    ".xml": "application/xml",
    ".csv": "text/csv",
    ".png": "image/png",
    ".jpg": "image/jpeg",
    ".jpeg": "image/jpeg",
    ".gif": "image/gif",
    ".webp": "image/webp",
    ".svg": "image/svg+xml",
  }[extension] || "application/octet-stream";
}

async function filesUnder(directory) {
  const entries = await readdir(directory, { withFileTypes: true });
  const files = [];
  for (const entry of entries.sort((a, b) => a.name.localeCompare(b.name))) {
    const filePath = join(directory, entry.name);
    if (entry.isDirectory()) files.push(...await filesUnder(filePath));
    else files.push(filePath);
  }
  return files;
}

function quote(value) {
  return JSON.stringify(value);
}

const files = await filesUnder(sourceRoot);
const entries = [];
const manifest = [];
const now = new Date().toISOString();

for (const filePath of files) {
  const bytes = await readFile(filePath);
  const relativePath = toPosixPath(relative(sourceRoot, filePath));
  const virtualPath = `/skills/${relativePath}`;
  const digest = createHash("sha256").update(bytes).digest("hex");
  const metadata = await stat(filePath);
  const modifiedAt = metadata.mtime.toISOString();
  const mimeType = mimeTypeFor(filePath);
  const content = textExtensions.has(extname(filePath).toLowerCase())
    ? JSON.stringify(bytes.toString("utf8"))
    : `new Uint8Array(${JSON.stringify([...bytes])})`;

  entries.push(`  ${quote(virtualPath)}: { content: ${content}, mimeType: ${quote(mimeType)}, created_at: ${quote(now)}, modified_at: ${quote(modifiedAt)} }`);
  manifest.push(`  ${quote(virtualPath)}: ${quote(digest)}`);
}

const output = `// Generated by scripts/generate-h3-skill-bundle.mjs. Do not edit.\n\nexport const officialH3Skills = {\n${entries.join(",\n")}\n} as const;\n\nexport const officialH3SkillManifest = {\n${manifest.join(",\n")}\n} as const;\n`;

await mkdir(join(projectRoot, "src", "agent", "generated"), { recursive: true });
await writeFile(outputPath, output, "utf8");
console.log(`Generated ${files.length} official H3 skill files.`);
